+// DefaultBundleDir returns and creates the default directory for OCI bundles.
+func DefaultBundleDir() (string, error) {
+	dir, err := Dir()
+	if err != nil {
+		return "", err
+	}
+	bundlesDir := filepath.Join(dir, "bundles")
+	if err := os.MkdirAll(bundlesDir, 0755); err != nil {
+		return "", fmt.Errorf("creating image directory: %w", err)
+	}
+	return bundlesDir, nil
+}
+
+func parseOCIReference(repository string) (registry.Reference, error) {
+	if scheme, remainder, ok := strings.Cut(repository, "://"); ok {
+		if scheme != "http" && scheme != "https" && scheme != "flipt" {
+			return registry.Reference{}, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
+		}
+		repository = remainder
+		if scheme == "flipt" && !strings.Contains(repository, "/") {
+			repository = "local/" + repository
+		}
+	}
+	return registry.ParseReference(repository)
 }
